#ifndef XW_PLAYER_SLEEP_HOST_H
#define XW_PLAYER_SLEEP_HOST_H
#include "sleep_retirement.h"
/* Private native-owner adapter. The future native bridge must qualify the
 * image/callsite and keep context/ops alive. epoch shares the wireless handoff
 * epoch namespace; it must not be generated by an independent counter.
 * No hook or wake admission is installed by this API. */
struct xw_sleep_host {
 struct xw_sleep_retirement retirement;
 void *native_context;
 int (*native_valid)(void *,uint64_t);
 int (*native_ack)(void *);
};
int xw_player_sleep_host_begin(struct xw_sleep_host *,void *,
 int (*)(void *,uint64_t),int (*)(void *),uint64_t,unsigned long);
int xw_player_sleep_host_poll(struct xw_sleep_host *);
/* Trusted recovery observer only. Acknowledgement success alone is insufficient:
 * caller supplies fresh native recovery validation. No old lease is revived. */
int xw_player_sleep_host_resume(struct xw_sleep_host *,int (*)(void *,uint64_t));
#endif
